import { API_BASE_URL } from '../config/api';

export interface Profile {
  name: string;
  bio: string;
  avatarUrl: string | null;
}

export async function fetchProfile(): Promise<Profile> {
  const response = await fetch(`${API_BASE_URL}/me`);
  if (!response.ok) throw new Error(`Profile failed with status ${response.status}`);
  return (await response.json()) as Profile;
}

export async function updateProfile(profile: Profile): Promise<Profile> {
  const response = await fetch(`${API_BASE_URL}/me`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(profile),
  });
  if (!response.ok) throw new Error(`Save failed with status ${response.status}`);
  return (await response.json()) as Profile;
}

import { useCallback, useEffect, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, Image, StyleSheet, SafeAreaView, KeyboardAvoidingView, Platform, ActivityIndicator } from 'react-native';
import { fetchProfile, updateProfile } from '../services/profile';

const colors = {
  accent: '#f05039',
  muted: '#8a8f8a',
  bg: '#0f120e',
  surface: '#1a1f1a',
  borderAlt: '#2a2f2a',
  textMuted: '#a8ada6',
  text: '#f5f5f0',
  danger: '#ff6b5e',
  success: '#4ade80',
}

const BIO_MAX = 160;

export function ProfileEditScreen(): JSX.Element {
  const [name, setName] = useState('');
  const [bio, setBio] = useState('');
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

    const load = useCallback(async () => {
    try {
      const profile = await fetchProfile();
setName(profile.name);
setBio(profile.bio);
setAvatarUrl(profile.avatarUrl);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load your profile.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const valid = name.trim().length > 0;

  const save = useCallback(async () => {
    if (!valid || saving) return;
    setSaving(true);
    setError(null);
    setSaved(false);
    try {
      await updateProfile({ name: name.trim(), bio: bio.trim(), avatarUrl });
      setSaved(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed.');
    } finally {
      setSaving(false);
    }
  }, [valid, saving, name, bio, avatarUrl]);

  if (loading) return <SafeAreaView style={styles.safe}><ActivityIndicator color="{colors.accent}" style={styles.center} /></SafeAreaView>;

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.flex}>
        <View style={styles.content}>
          <TouchableOpacity style={styles.avatarWrap} onPress={() => setAvatarUrl('https://cdn.example.com/avatars/next.png')} accessibilityRole="button" accessibilityLabel="Change avatar">
            {avatarUrl ? <Image source={{ uri: avatarUrl }} style={styles.avatar} /> : <Text style={styles.avatarPlaceholder}>＋</Text>}
          </TouchableOpacity>
          <Text style={styles.label}>Name</Text>
          <TextInput
            value={name}
            onChangeText={setName}
            placeholder="Your name"
            placeholderTextColor="{colors.muted}"
            accessibilityLabel="Name"
            style={styles.input}
          />
          <Text style={styles.label}>Bio</Text>
          <TextInput
            value={bio}
            onChangeText={t => setBio(t.slice(0, BIO_MAX))}
            placeholder="Tell people about yourself"
            placeholderTextColor="{colors.muted}"
            multiline
            accessibilityLabel="Bio"
            style={[styles.input, styles.bio]}
          />
          <Text style={styles.counter}>{bio.length}/{BIO_MAX}</Text>
          {error && <Text style={styles.error}>{error}</Text>}
          {saved && <Text style={styles.success}>Saved.</Text>}
          <TouchableOpacity style={[styles.save, !valid && styles.disabled]} disabled={!valid || saving} onPress={save} accessibilityRole="button">
            {saving ? <ActivityIndicator color="{colors.bg}" /> : <Text style={styles.saveText}>Save profile</Text>}
          </TouchableOpacity>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  flex: { flex: 1 },
  center: { marginTop: 40 },
  content: { padding: 20 },
  avatarWrap: { width: 96, height: 96, borderRadius: 48, backgroundColor: colors.surface, alignItems: 'center', justifyContent: 'center', alignSelf: 'center', marginBottom: 20, borderWidth: 2, borderColor: colors.borderAlt },
  avatar: { width: 96, height: 96, borderRadius: 48 },
  avatarPlaceholder: { color: colors.muted, fontSize: 32 },
  label: { color: colors.textMuted, fontSize: 12, marginBottom: 6, marginTop: 12 },
  input: { backgroundColor: colors.surface, color: colors.text, borderRadius: 6, padding: 12, borderWidth: 1, borderColor: colors.borderAlt },
  bio: { minHeight: 80, textAlignVertical: 'top' },
  counter: { color: colors.muted, fontSize: 11, textAlign: 'right', marginTop: 4 },
  save: { backgroundColor: colors.accent, borderRadius: 6, paddingVertical: 14, alignItems: 'center', marginTop: 20 },
  saveText: { color: colors.bg, fontWeight: '700' },
  disabled: { opacity: 0.5 },
  error: { color: colors.danger, marginTop: 12 },
  success: { color: colors.success, marginTop: 12 },
});
